function isValidDate(dateString) {
  const datePattern = /^\d{4}-\d{2}-\d{2}$/;
  if (!datePattern.test(dateString)) return false;
  const date = new Date(dateString);
  return date.toISOString().slice(0, 10) === dateString;
}

function parseDate(dateString) {
  if (!isValidDate(dateString)) {
    throw new RangeError(`Invalid date: ${dateString}`);
  }
  return new Date(dateString);
}

function formatDate(date) {
  return date.toISOString().slice(0, 10);
}

function getWeekday(date) {
  return date.getUTCDay();
}

function isWeekend(date) {
  const day = getWeekday(date);
  return day === 0 || day === 6;
}

function getObservedHolidays(holidays) {
  const observed = new Set();
  const weekendHolidays = [];

  holidays.forEach(holiday => {
    const date = parseDate(holiday);
    if (isWeekend(date)) {
      weekendHolidays.push(date);
    } else {
      observed.add(formatDate(date));
    }
  });

  weekendHolidays.sort((a, b) => a - b);

  weekendHolidays.forEach(date => {
    let observedDate = new Date(date);
    observedDate.setUTCDate(observedDate.getUTCDate() + (getWeekday(observedDate) === 6 ? 2 : 1));
    while (observed.has(formatDate(observedDate)) || isWeekend(observedDate)) {
      observedDate.setUTCDate(observedDate.getUTCDate() + 1);
    }
    observed.add(formatDate(observedDate));
  });

  return observed;
}

export function isBusinessDay(date, holidays = []) {
  const parsedDate = parseDate(date);
  const observedHolidays = getObservedHolidays(holidays);
  return !isWeekend(parsedDate) && !observedHolidays.has(formatDate(parsedDate));
}

export function addBusinessDays(date, n, holidays = []) {
  if (!Number.isInteger(n)) {
    throw new RangeError(`Invalid number of days: ${n}`);
  }

  let currentDate = parseDate(date);
  const observedHolidays = getObservedHolidays(holidays);

  const step = n >= 0 ? 1 : -1;
  let businessDaysCounted = 0;

  while (businessDaysCounted !== Math.abs(n)) {
    currentDate.setUTCDate(currentDate.getUTCDate() + step);
    if (isBusinessDay(formatDate(currentDate), holidays)) {
      businessDaysCounted++;
    }
  }

  if (n === 0 && !isBusinessDay(formatDate(currentDate), holidays)) {
    while (!isBusinessDay(formatDate(currentDate), holidays)) {
      currentDate.setUTCDate(currentDate.getUTCDate() + 1);
    }
  }

  return formatDate(currentDate);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startDate = parseDate(start);
  const endDate = parseDate(end);

  if (startDate.getTime() === endDate.getTime()) return 0;

  const step = startDate < endDate ? 1 : -1;
  let currentDate = new Date(startDate);
  let businessDaysCounted = 0;

  while (currentDate.getTime() !== endDate.getTime()) {
    currentDate.setUTCDate(currentDate.getUTCDate() + step);
    if (isBusinessDay(formatDate(currentDate), holidays)) {
      businessDaysCounted += step;
    }
  }

  return businessDaysCounted;
}
